<?php require_once __DIR__.'/bootstrap.php';auth();$p=db();$msg='';$err='';if($_SERVER['REQUEST_METHOD']==='POST'){check_token();if(($_POST['action']??'')==='delete'){$q=$p->prepare('DELETE FROM noora_articles WHERE id=?');$q->execute([(int)$_POST['id']]);$msg='مقاله حذف شد.';}else{$id=(int)($_POST['id']??0);$title=trim($_POST['title']??'');$slug=strtolower(trim(preg_replace('/[^a-zA-Z0-9-]+/','-',$_POST['slug']??''),'-'));$cat=trim($_POST['category']??'');$excerpt=trim($_POST['excerpt']??'');$body=trim($_POST['body']??'');$img=trim($_POST['image_url']??'');$status=($_POST['status']??'draft')==='published'?'published':'draft';if(!$title||!$slug)$err='عنوان و شناسه انگلیسی لازم است.';elseif($img&&!filter_var($img,FILTER_VALIDATE_URL))$err='آدرس تصویر معتبر نیست.';else try{if($id){$q=$p->prepare('UPDATE noora_articles SET title=?,slug=?,category=?,excerpt=?,body=?,image_url=?,status=? WHERE id=?');$q->execute([$title,$slug,$cat,$excerpt,$body,$img,$status,$id]);}else{$q=$p->prepare('INSERT INTO noora_articles(title,slug,category,excerpt,body,image_url,status) VALUES(?,?,?,?,?,?,?)');$q->execute([$title,$slug,$cat,$excerpt,$body,$img,$status]);}$msg='مقاله ذخیره شد.';}catch(Throwable $e){$err='ذخیره انجام نشد؛ شاید شناسه تکراری باشد.';}}}
$edit=null;if(isset($_GET['edit'])){$q=$p->prepare('SELECT * FROM noora_articles WHERE id=?');$q->execute([(int)$_GET['edit']]);$edit=$q->fetch()?:null;}$rows=$p->query('SELECT * FROM noora_articles ORDER BY id DESC')->fetchAll();head('مدیریت مقاله‌ها');if($msg)echo '<p class="success">'.h($msg).'</p>';if($err)echo '<p class="error">'.h($err).'</p>';?><section class="panel"><h2><?=$edit?'ویرایش مقاله':'افزودن مقاله'?></h2><form method="post"><input type="hidden" name="csrf" value="<?=h(token())?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=(int)($edit['id']??0)?>"><label>عنوان</label><input name="title" required value="<?=h($edit['title']??'')?>"><label>شناسه انگلیسی یکتا</label><input name="slug" required placeholder="slow-living-guide" value="<?=h($edit['slug']??'')?>"><label>دسته‌بندی</label><input name="category" value="<?=h($edit['category']??'')?>"><label>وضعیت</label><select name="status"><option value="draft" <?=($edit['status']??'draft')==='draft'?'selected':''?>>پیش‌نویس</option><option value="published" <?=($edit['status']??'')==='published'?'selected':''?>>منتشرشده</option></select><label>آدرس تصویر</label><input type="url" name="image_url" value="<?=h($edit['image_url']??'')?>"><label>خلاصه</label><textarea name="excerpt" rows="2"><?=h($edit['excerpt']??'')?></textarea><label>متن مقاله</label><textarea name="body" rows="6"><?=h($edit['body']??'')?></textarea><button class="btn">ذخیره مقاله ←</button> <?php if($edit):?><a href="articles.php">انصراف</a><?php endif;?></form></section><section class="panel"><h2>مقاله‌های موجود (<?=count($rows)?>)</h2><div class="tablewrap"><table><tr><th>عنوان</th><th>شناسه</th><th>وضعیت</th><th>عملیات</th></tr><?php foreach($rows as $r):?><tr><td><?=h($r['title'])?></td><td><?=h($r['slug'])?></td><td><?= $r['status']==='published'?'منتشرشده':'پیش‌نویس'?></td><td><a href="?edit=<?=(int)$r['id']?>">ویرایش</a> <form class="inline" method="post" onsubmit="return confirm('حذف شود؟')"><input type="hidden" name="csrf" value="<?=h(token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><button class="danger">حذف</button></form></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="4">هنوز مقاله‌ای ثبت نشده.</td></tr><?php endif;?></table></div></section><?php foot();?>
